      "program_increment": "10-week planning and delivery cycle",
      "key_ceremony": "PI Planning (whole train aligns)",
      "pi_planning_timeline": {
        "day_1": "Vision and capacity planning",
        "day_2": "Team breakouts and story planning",
        "day_3": "Team presentations and risk management"
      },
      "release_train_engineer": "Coordinates across teams, removes blockers"
    },

    "team_level": {
      "sprint_duration": "2 weeks (within the 10-week PI)",
      "sprints_per_pi": "5 sprints per Program Increment",
      "ceremonies": ["Sprint planning", "Daily standup", "Sprint review", "Retrospective"]
    },

    "synchronization": {
      "dependency_tracking": "Visible across teams",
      "risk_management": "Escalated to Program level",
      "metrics": "Program predictability, PI objectives completion"
    }
  }
}
